"""A-board comment review after the five-file physical pilot."""
from comment_review import ROOT, CACHE, apply_batch, write_json, files, spans
from finish_b_comments import changes as shared_changes, blocks

changes={
'scale_engine.v':[('============================================================================','Load-time nearest-neighbour scaling into DEST_W x DEST_H pixels.\nFill and emit share two row banks; row IDs versus need_sy determine reuse.\nA completed frame must contain all destination pixels and drain its source.\nNonelastic input reserves space for an in-flight 512-byte sector; its row\nwatchdog reuses a held row or black and increments fallback_count. Elastic\ninput waits for the exact row, with bounded timeouts owned by its caller.\nImage acceptance requires zero fallback/dropped bytes and all source rows.'),('Pause early','For sector input, pause at 3072: 3072+512=3584 fits the 4096-byte FIFO.\nElastic input stops at !in_ready each cycle; scale its diagnostic hysteresis\nwith FIFO depth. Nonelastic thresholds remain 3072/1024.'),('extra bit distinguishes','The extra pointer bit distinguishes full from empty.\nBuffer the short FF-to-EMB address path without changing its address or latency.'),('TD packing','TD packing uses EQN and functional simulation uses INIT; both encode identity.'),('routed hold','Protect the write-address hold path with the same zero-cycle buffer.'),('A bank may','Reuse an empty bank or a row older than need_sy. Once rendering finishes,\nflush the remaining source rows.'),('pop_issue MUST','pop_issue must remain independent of bd_v. If FIFO reads waited for\nf_consume, an empty byte latch could never fill. Fetch while a fill is\nactive or another row may begin, then consume through the one-byte latch.'),('L1: ping-pong','Declare the line-buffer connections before instantiation to avoid implicit one-bit nets.'),('Enabled read','Hold bd when pop_issue is low so a stalled fill keeps its byte.\nThis block is its sole driver.'),('This metadata','Keep stage-one metadata with its pixel token through stalls.'),('--------- fill','Invalidate the target bank when filling starts; emit must not read a\npartly overwritten row.'),('Watchdog (C1)','For nonelastic input, reuse a held row on watchdog expiry or emit black.'),('Remote source','Elastic input may pause. Wait for the exact row; the enclosing loader\nrejects timeout or incomplete-frame failures without publishing fallback.'),('Output is complete','Drain trailing source rows after output completes, before frame_done,\nso the BMP loader consumes the entire payload.')],
'a_osd.v':[('Both numbers','Both inputs stay fixed through vertical blank. Two 11-cycle BCD jobs\nfinish over 35000 clocks before the next active pixel.'),('2 audio meter','Draw the 12x12 meter cells below subtitles; hint, fault and menu overlays keep priority.')],
'a_top.v':[('Visible transaction','Keep the visible transaction independent of the held loader transaction.'),('E1 flag0','E1 flag 0 selects lookahead direction. Preserve the nearer prefetched frame\nwhile filling the second; displayed and previous frames keep their slots.'),('Include progress','Show progress for the held prefetch while the new target waits.'),('Metadata shares','Publish metadata with the qualified cache tag/CRC. Loader abort clears\nits working record while cached records remain valid.'),('1: A','A does not consume query I; debug_select treats it as unsupported.')],
'atlas_ingest.v':[('Layered page','Decode layered pages with full-height foreground. Ordinary pages use their\nown loader. Read back each auxiliary and BASE word against its source asset.'),('Exact common','Reuse y products without adding state: 213*y = 3*(64*y+7*y);\n442*y = 2*(213*y)+16*y.'),('FG is consumed','Read FG for y>=320; below that, pixel_address selects BG/BASE.')],
'audio_fx.v':[('One signed','Share one signed 28x24 MAC across separate L/R states and 63-tap histories.\nPublish each accepted frame after exactly LATENCY clocks.'),('Signed round','Nearest rounding, ties away from zero: add half for positive values and\nhalf-1 for negative values before the arithmetic shift.'),('Resume retains','Keep filter history on resume. Start a measurement epoch that excludes\nthe 256-sample fade-in.')],
'audio_level_meter.v':[('2 minimal','Measure the audible PCM peak per video frame. Rise immediately and fall\none cell per frame; meter_end=level+4 marks the first dark cell in 4..34.'),('gain x2','Apply saturated x2 display gain to the L/R OR of one\'s-complement magnitudes.')],
'audio_metrics.v':[('Direct synchronous','Project left PCM onto the 3 kHz I/Q reference before and after filtering.\nThis calculation is independent of the filter MAC. low_pre/low_post stay zero;\ncompleted high_pre/high_post values carry block_id and record_valid.'),('op:','op={post,quadrature}: pre I, pre Q, post I, post Q.'),('Prepare each','Present each RAM address in the state before its operand is used.'),('Retain the last','Keep the last complete record through pause/HOLD; discard the partial block.')],
'board_inputs.v':[('Configuration initialization','Power-on reset release is independent of the four user buttons.'),('Same release','Register release when startup is 1022, on the same edge that makes &startup true.'),('One shared','Share the millisecond tick. A key must first be released before it is armed.')],
'crossfade_blend.v':[('One aligned','Buffer one aligned old-image block. Pair synchronous reads with new-image\nbeats and use three signed difference products for RGB blending.'),('No reset','Validity hides stale pixels, so neither RAM data nor its read register needs reset.')],
'debug_select.v':[('Release diagnostics','Three common queries plus a board-specific query select diagnostics.\nUnsupported queries preserve the current view; HAS_I=0 disables I on A.')],
'fade_transition.v':[('Frame-boundary','The control domain owns swap requests. The pixel domain changes fade state\nat frame boundaries and commits after a complete black frame, hiding the swap.'),('Control domain','Detect the player request and synchronize the black-frame commit back to control.'),('Pixel domain','Update ramp only at frame_start; hold alpha_sel through the visible frame.'),('33-point','Use 33 rounded smoothstep entries with exact endpoints. Index by frame,\nso no curve multiplication runs at the pixel rate.'),('9-bit','Use 9-bit opacity and 17-bit products to preserve all RGB bits at full light.'),('No active raster','Acknowledge without waiting if there is no active raster.'),('Fail-open','Leave black-out if the reader fails to acknowledge.')],
'filter_display.v':[('Display qualification','A commit means one completed measurement. Qualify the displayed result\nwithout changing measurement values or thresholds.'),('Bypass only','Apply live disqualification and identity changes immediately, so a frame\nlatch on the same edge cannot keep the previous context\'s number.'),('An invalid','Remove the numeric result immediately on an invalid measurement.')],
'filter_metrics.v':[('Reuse the qualified','Use the qualified 1024-frame projections and integer dB conversion.\nCarry the completed block\'s epoch, mode and track into its status.'),('No numeric','Suppress numbers when live qualification fails. Quiet or muted input\ncannot establish successful attenuation.')],
'filter_record.v':[('Existing G1a','grade_record={status[2:0],approximate_dB[5:0],context[3:0]}.\nKeep full measurement identity local for qualification.'),('Source metrics','The completed pair stays fixed for at least 25600 clocks; conversion needs\nat most 43. Abort on epoch, block or context change.')],
'fit_geometry.v':[('Fixed 640x480','Fit into 640x480 using three operations on one 22-step restoring divider.\nready holds the completed geometry until the next load.'),('Explicitly wide','Keep these products 22 bits wide; the maximum is 1,310,080.'),('The first storage','Storage begins at the bottom row. Assign an odd spare row to the bottom border.')],
'geometry_display.v':[('Six decimal','Convert six decimal values on one 16-step double-dabble unit. Publish\nthem together only if the qualified geometry still matches.')],
'image_media.v':[('memory_ready','Synchronize memory_ready from the SDRAM PLL domain into SYS. The request\nand response buses use the mem_client toggle handshake and bundled-data limits.'),('The mailbox','Publish the mailbox in vertical blank and hold it during active video.'),('A P frame','Diagnostic P word 3 exposes the meter level in its low five bits.'),('2: meter','Meter input is audible HDMI PCM: zero on pause, mute, an inactive page or fault.')],
'layer_compositor.v':[('Full-height','Compose full-height foreground with dwell/lag motion and Q2 interpolation.\nKeep pixel metadata aligned through the six-cycle pipeline.'),('The next legal','The next consumer is the following 800x525 frame boundary, leaving time\nfor a synchronous motion-table read. Entry 0 and the first reset-release\nfallback are both zero.')],
'layer_fault_cdc.v':[('Pixel fault','The pixel fault stays sticky until pixel reset; synchronize that level into SYS.')],
'layer_prefetch.v':[('P2:','One sample per plane, with four published rows per plane and independent retirement.'),('Offset low8','Offsets start at zero and advance by 256, so their low eight bits stay zero.\n256*(block+1)<=end reduces to block<floor(end/256) without 19-bit overflow.')],
'layered_image_ingest.v':[('Keeps the released','Route ordinary pages through their existing loader and verification path.')],
'load_progress.v':[('Exact byte','Compare byte progress against ceil(k*total/8). Show it only for the\naccepted foreground transaction.'),('C2:','For integers, received>=ceil(te/8) iff 8*received>=te.\n8*received < 2^35; te <= 9*(2^32-1) < 2^36.')],
'media_memory.v':[('Shared 2M','Share 2M x 32 SDRAM between two independent 10 MHz link-clock clients.\nThe physical interface uses aligned four-beat requests.'),('Two 307200','Reserve two 307200-word working frames and four resident scene-cache slots.'),('Ordinary pages','Keep ordinary-page priority. For layered frames, serve BASE FIFO first,\nthen a ready auxiliary block, then clients. With low-water 512, a\n274-cycle burst leaves at least 375 pixels.'),('The two reserved','Two read-only diagnostic addresses lie outside the image/work buffers\nand return through the same acknowledged response bundle.'),('A may queue','Permit the first preload to wait through SDRAM power-up and initialization.')],
'mem_client.v':[('One outstanding','Allow one outstanding request. Hold each request/response bundle until\nthe matching toggle has crossed the other domain\'s two synchronizer stages.')],
'menu_control.v':[('Automatic transactions','Automatic transactions own these six bits; menu state and values stay local.'),('Compact coherent','Build the compact record once in SYS and publish at a pixel-frame boundary.\nUse the reserved upper 16 bits, keeping mailbox and protocol widths fixed.'),('The request is','A key event increments generation as it creates the request. The link\nsends that updated identity with the action.'),('A long gesture','Start a fresh menu timeout on a long gesture, as for ev keys.'),('A physical event','Give the physical event priority, but consume the reliable incoming key once.'),('This OK','OK here accepts a normal page transition; it does not queue recording.'),('Shared metadata','Share metadata only; ordinary menu values do not select automatic phases.')],
'scale_dda.v':[('============================================================================','Incremental nearest-neighbour source index: floor(dst*SRC/DEST).\nFor each destination step, add s to rem and q to idx; a carry adds one\nmore to idx and subtracts DEST from rem. q=SRC/DEST, s=SRC-q*DEST.\nrem,s < DEST, so rem+s < 2*DEST and fits REM_W+1 bits.\nThe step uses one adder and one subtractor per axis.')],
'scale_linebuf.v':[('============================================================================','Two row banks let fill prepare the next source row while emit reads the\ncurrent row. The scaler assigns ownership from row IDs versus need_sy.\nHold read data during stalls with clock enable. The production 2048x24\nshape uses native BRAM; other parameter values use separate inferred banks.'),('The production','Pack both 2048x24 banks into three 32K byte lanes. Read CE holds data on stalls.'),('Each bank','Keep generic-bank reads separate, then mux their registered outputs.\nPutting the selection inside the array read prevents this intended RAM mapping.'),('Registered read','Read latency is one cycle. rd_en also holds the bank selector,\nso data remains fixed during out_ready backpressure.')],
'scene_bmp_stream.v':[('one CRC','Feed the CRC-qualified remote byte stream into the aspect-fit scaler.\n640x480 selects identity geometry on the same decoder and FIFO.'),('Predict the next','Register the next timeout predicate with the counter. At the decision\nedge it equals timer>=TIMEOUT_CYCLES-1; an already-due timeout still wins\nover progress arriving on that edge.'),('Released engines','The scaler consumes each in_valid pulse. Pulse it only for accepted\nremote bytes, since the upstream stream can wait.'),('ARM raises','ARM asserts start_engine before the scaler clears its prior out_v.\nMask launch, HEADER and IDLE output, including abort/restart.'),('Input is retained','Keep input upstream until ready; this interface can apply backpressure.')],
'scene_i2s_rx.v':[('Oversample','Oversample the 64-BCLK/channel I2S stream in the pixel domain.\nAfter reset or a mid-channel start, wait for falling LRCK and then\na complete left/right pair before publishing.'),('LRCK and DATA','LRCK and DATA change at falling BCLK. Match their three input stages;\nthe first sampled bit is the I2S delay bit.'),('The edge','The edge with changed LRCK contains the previous channel\'s last padding\nbit, so it completes that channel.')],
'scene_image_buffer.v':[('A\'s independent','Copy each CRC-approved packet into A\'s 512-byte image buffer before\nwaiting on SDRAM. This releases parser RAM for READY/APPLIED/analysis.\nACK retires B\'s held block; only IMAGE_REQ grants the next credit.\nACK duplicates without copying or publishing the block twice.')],
'scene_image_ingest.v':[('Four disjoint','Cache slots occupy [614400,1843200); work frames occupy [0,614400).\nPublish a slot after source and target complete, display-order CRC passes,\nand independent SDRAM readback matches the writer-order CRC.'),('LOAD and READ','LOAD and readback CRC are exclusive and share one byte datapath.'),('Large, throttled','Measure missing progress for throttled files. Request acceptance alone\ndoes not complete work or reset the progress requirement.')],
'scene_uart.v':shared_changes['scene_uart.v'],
'scene_video_observer.v':[('The pixel-domain','Hold the pixel ID until the next first visible pixel with a new ID.\nSYS compares it after the two-stage toggle capture.')],
'sdram.v':[('Adapted from','SDRAM wrapper derived from official lab_ex4 SD/sram.v, retaining the\napplication interface and PHY instance. The encrypted sdr_as_ram is unchanged.')],
'sdram_word_adapter.v':[('Single-word','Adapt single-word requests to APUG011 aligned four-word bursts. The vendor\ncore needs a continuous request to issue READ/WRITE. Mask unused write\nbeats and select the requested read beat; keep the burst uninterrupted.'),('Board capture','The captured 41.667 MHz / 180-degree interface has dout one clock ahead\nof valid. Register dout every clock, including the clock before valid.'),('The vendor','The vendor propagates this mask to DQM outside writes too. Keep DQM low\non reads so SDRAM can drive the bus.'),('No fabricated','Leave a missing response to the caller\'s read watchdog, then drain the adapter.')],
'text_engine.v':[('Exactly three','Three registered stages: glyph index, shared 16-bit glyph row, then RGB/sync.'),('Exact radix','Decompose /24 as /3 on the upper seven bits plus the low three bits.\nPreserve the saturated column and low-five-bit remainder for all 1024 inputs.'),('One registered','Native read plus bank-select register sets the read latency. Pad only\nthe last partial bank; return zero for absent banks.')],
'tf_fifo_writer.v':[('Backpressured','BMP pixels arrive bottom row first. Reverse row addresses while writing\n0x00RRGGBB into SDRAM top to bottom. The memory mailbox accepts one word\nat a time, passing backpressure through the scaler to the source FIFO.'),('Synchronous cancellation','Cancel synchronously. Wait for the memory mailbox to drain before\nstarting another ingest transaction.')],
'ui_link.v':shared_changes['ui_link.v']+[('The active body','Hold the active body through ACK. Let the consumer sample result_valid\nbefore the queued body replaces it on the following clock.')],
'video_burst_reader.v':[('Video reader','Read ahead through the official asynchronous FIFO interface.'),('The generated','The FIFO asserts reset asynchronously and releases it in each domain.\nWait four additional mclk edges after shared reset release before writing\nthe first SDRAM burst.'),('This bundle','Capture the frame bundle at a raster boundary. Keep it held until both\nSDRAM prefetch and pixel CRC complete.'),('Linear reflected','Reflected CRC32 transform, checked independently against zlib.'),('Ordered runs','Emit ordered runs from aligned 256-word blocks. Advance only when the\nbeat and locked source match the next pixel. Restart the block at a\nsource boundary, discarding emitted prefixes and wrong-source suffixes.\nLeft/top wipe needs at most three runs per block, including row wrap.'),('routed FF','Zero-cycle buffer protects the routed FF-to-EMB data hold path.'),('A\'s existing','Between requests, the read-only client may sample the last complete\nordinary burst. Exclude epoch/flush and mixed-image bursts; observation\ndoes not stall the pixel or FIFO path.'),('ID changes','Change ID with the final player swap bundle.')],
'video_fifo.v':[('Official Anlogic','SHOW_AHEAD exposes the current pixel before pop. The Anlogic core owns\nGray-pointer CDC, BRAM and reset/flag timing for this prefetch FIFO.'),('The official FIFO','Combine both frame-side flush requests into the shared asynchronous\nreset so neither pointer retains an old frame.'),('The generated core','Zero-extend the generated 512-word FIFO\'s nine-bit counts to the\nwrapper\'s AW+1 count width.')],
'video_fx.v':[('Pixel-domain','Latch effects at the first active pixel and hold through the frame.\nUse the video reader\'s committed pixel-domain ID to bind those controls.'),('0: legacy','ARITH_MODE: 0 general arithmetic; 1 shared-DSP presets; 2 exact shift/add.'),('The control bundle','Debounce holds the control bundle across many link clocks. Sample it\ntwice in the pixel domain before committing at frame_start.'),('floor(3*','floor(3*(v-128)/2)+128 = v+floor(v/2)-64.\nfloor(5*(v-128)/4)+128 = v+floor(v/4)-32.\nThe shared 10-bit sum spans -64..318; its upper two bits select saturation.')],
'video_pll.v':[('PLL divisors','Official clk_wize.v divisors: 50 MHz input, 125 and 25 MHz outputs.\nExpose lock and leave unused outputs disconnected.'),('Internal C0','Close feedback through C0 to avoid uncompensated local routing.')],
'voice_dtw.v':[('Serialized symmetric2','Evaluate symmetric2 L1 DTW serially over 16 dimensions. All references\nhave 32 frames, giving the same N+32 denominator. Compare class costs\ndirectly and share one multiplier for threshold and margin checks.\nHold the input utterance until done or abort.'),('Cancel immediately','Cancel stops ownership and decisions. Reinitialize these operands before\nthe next use; their update control does not need the wide cancellation cone.')],
'voice_rx.v':[('Retains the CRC','Hold the CRC-qualified packet until every synchronous payload read completes.\nA owns recognition; B owns playback and one-shot actions.')],
'voice_utterance.v':[('MIC feature','Collect MIC features in circular utterance RAM and classify serially.\nBusy drops this optional branch; identity changes and invalid frames\nstill cancel an in-flight classification.'),('Peak is data','Cancellation clears ownership and blocks RAM writes and matcher actions.\npeak_data is unused in LISTEN and rebuilt at LISTEN-to-SPEECH; keep\nthe cancel/admit fanout outside its wide update control.'),('Registered observations','Register VAD observations without feeding them back into admission.')],
}

def run():
    all_edits={};reasons={}
    for name,rows in changes.items():
        data=(ROOT/'source/a'/name).read_bytes();edits=[]
        for prefix,new in rows:
            found=[(a,b) for a,b in blocks(data) if data[a:b].decode('utf-8').startswith('// '+prefix)]
            assert len(found)==1,(name,prefix)
            a,b=found[0];indent=data[data.rfind(b'\n',0,a)+1:a].decode('utf-8')
            if indent.strip():indent=' '
            edits.append((data[a:b].decode('utf-8'),('\n'+indent).join('// '+s for s in new.splitlines())))
        all_edits[name]=edits
        reasons[name]='按当前数据路径重写，保留位宽、时序、CRC、缓存所有权及取消/复位条件，删除过时版本比较和重复概述。'
    names=list(all_edits)
    for i in range(0,len(names),5):
        group=names[i:i+5];apply_batch('a',f'{2+i//5:02d}_full',{n:all_edits[n] for n in group},{n:reasons[n] for n in group})
    write_json(ROOT/'reports/REVIEW_A.json',dict(changes=list(changes),other_files={p.name:'保留厂商生成说明、来源署名、精确接口/参数短注释，或该文件无描述性注释；试点文件沿用已记录改写。' for p in files(ROOT,'a') if p.name not in changes},opaque_ip='Never opened or modified.'))

if __name__=='__main__':run()
